import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"Edge runtime testing — 8-axis SSOT for kiwa @kiwa/edge v0.2","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/edge-runtime-testing.md","filePath":"concepts/edge-runtime-testing.md"}'),s={name:"concepts/edge-runtime-testing.md"};function r(a,e,i,n,l,u){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="edge-runtime-testing-—-8-axis-ssot-for-kiwa-kiwa-edge-v0-2" tabindex="-1">Edge runtime testing — 8-axis SSOT for kiwa <code>@kiwa/edge</code> v0.2 <a class="header-anchor" href="#edge-runtime-testing-—-8-axis-ssot-for-kiwa-kiwa-edge-v0-2" aria-label="Permalink to &quot;Edge runtime testing — 8-axis SSOT for kiwa `@kiwa/edge` v0.2&quot;">​</a></h1><p>Introduced in v1.24-1, <code>@kiwa/edge</code> v0.2 raises the edge mock harness from a <strong><code>fetch</code> handler invocation + minimal KV / R2 / D1 / DurableObject stubs</strong> surface (v0.1) to a full <strong>advanced edge semantics</strong> surface. Where v0.1 gave you <code>invokeEdgeHandler</code> + <code>createKvNamespace</code> and a shallow DurableObject stub, v0.2 layers <strong>8 axes</strong> of platform-neutralised edge behaviour on top.</p><p>The 8 axes are the observable envelope every real edge platform (Cloudflare Workers, Vercel Edge, Deno Deploy) converges on — mapped to the same neutral event names + state machines — so tests write once and re-run against any platform. This document is the SSOT for what each axis exists to test, what state machine it defines, and which platform-specific behaviours it neutralises.</p><h2 id="why-8-axes-why-now" tabindex="-1">Why 8 axes, why now <a class="header-anchor" href="#why-8-axes-why-now" aria-label="Permalink to &quot;Why 8 axes, why now&quot;">​</a></h2><p>Edge testing has three failure modes that a <code>fetch</code>-only mock cannot catch.</p><ul><li><strong>Stateful drift</strong>. A Durable Object&#39;s real lifecycle is not just <code>create → serve</code> — it is a 4-event trace (<code>created</code> / <code>requested</code> / <code>alarm-fired</code> / <code>storage-written</code>) with a transactional storage guarantee and a Hibernation-driven wake-up. Tests that only assert on a <code>Response.status</code> miss the state-machine drift, and production bugs surface as lost storage writes or duplicate broadcasts.</li><li><strong>Consistency envelope</strong>. Real edge KV trades strong consistency for low-latency edge reads (Cloudflare KV, Vercel Edge Config, Deno KV replicas). Tests that skip the primary-vs-replica distinction miss read-your-writes bugs and let merchant apps ship with stale-read races.</li><li><strong>Cross-platform fidelity</strong>. Cloudflare fires cron on 3 sources (scheduled + queue + email), Vercel exposes only scheduled + queue, Deno Deploy exposes scheduled + queue. Streaming Response backpressure is measured in bytes on Vercel, in chunks on Cloudflare. A neutral test surface makes these differences <strong>explicit assertions</strong>, not silent regressions.</li></ul><p>The 8 axes below are the smallest set that reproduces the full edge envelope across the 3 target platforms. Each axis is an independent module under <code>@kiwa/edge/semantics/*</code>; each provides pure functions that operate on a session object and emit a strongly typed <code>AxisStep</code> sequence.</p><h2 id="axis-1-—-durable-object" tabindex="-1">Axis 1 — Durable Object <a class="header-anchor" href="#axis-1-—-durable-object" aria-label="Permalink to &quot;Axis 1 — Durable Object&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce Cloudflare Durable Objects (and their session-affine analogues on Vercel + Deno Deploy). A single stateful actor pinned to one edge location — created once, receives fetch requests that pin it <code>active</code>, wakes on a scheduled alarm, and persists to transactional storage.</p><p><strong>State machine</strong>. <code>initialized</code> → <code>active</code> (loops on <code>requestDurableObject</code> / <code>fireAlarm</code> / <code>writeStorage</code>) → <code>hibernated</code> / <code>terminated</code> (out of scope for v0.2).</p><p><strong>Key functions</strong>.</p><ul><li><code>createDurableObject({ id, platform })</code> — creates a session in <code>initialized</code> state, emits <code>durable-object.created</code></li><li><code>requestDurableObject(session, { url })</code> — pins the instance <code>active</code>, bumps <code>requestCount</code>, emits <code>durable-object.requested</code></li><li><code>fireAlarm(session)</code> — re-activates the instance from a scheduled alarm, emits <code>durable-object.alarm-fired</code></li><li><code>writeStorage(session, { key, value })</code> — persists a key/value pair to <code>storageKeys</code>, emits <code>durable-object.storage-written</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes DO storage survives a broadcast failure but forgets to wrap the writes in a transaction. Test catches it by asserting the ordered <code>history</code> sequence includes the rollback state before finalisation.</p><h2 id="axis-2-—-websocket-edge" tabindex="-1">Axis 2 — WebSocket edge <a class="header-anchor" href="#axis-2-—-websocket-edge" aria-label="Permalink to &quot;Axis 2 — WebSocket edge&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce edge WebSocket lifecycle. All 3 platforms accept a <code>101 Switching Protocols</code> upgrade (Cloudflare <code>WebSocketPair</code>, Vercel edge websockets, Deno <code>Deno.upgradeWebSocket</code>) but expose different telemetry strings.</p><p><strong>State machine</strong>. <code>pending</code> → <code>open</code> → <code>closed</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>requestWebSocketUpgrade({ id, platform })</code> — creates a session in <code>pending</code>, emits <code>websocket.upgrade-requested</code></li><li><code>acceptWebSocket(session)</code> — transitions to <code>open</code>, emits <code>websocket.accepted</code></li><li><code>sendMessage(session, { data })</code> — appends to <code>messages</code>, emits <code>websocket.message</code>, rejects unless the socket is <code>open</code></li><li><code>closeWebSocket(session, { code })</code> — transitions to <code>closed</code>, emits <code>websocket.closed</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app tries to <code>sendMessage</code> on a socket that already closed on the Hibernation wake-up. Test catches it by asserting the throw + expected state.</p><h2 id="axis-3-—-edge-kv" tabindex="-1">Axis 3 — Edge KV <a class="header-anchor" href="#axis-3-—-edge-kv" aria-label="Permalink to &quot;Axis 3 — Edge KV&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce edge KV with a read-through per-POP cache. Cloudflare KV, Vercel Edge Config, Deno KV all trade strong consistency for low-latency edge reads.</p><p><strong>Consistency states</strong>. <code>consistent</code> (Deno KV primary) / <code>eventually-consistent</code> (Cloudflare KV, Vercel Edge Config, Deno KV replicas).</p><p><strong>Key functions</strong>.</p><ul><li><code>createEdgeKvSession({ platform, state })</code> — opens a KV session with a backing <code>store</code> + read-through <code>cache</code></li><li><code>kvRead(session, { key })</code> — populates the cache on a cold read, emits <code>kv.read</code> (cold) / <code>kv.cache-hit</code> (warm) / <code>kv.cache-miss</code> (absent)</li><li><code>kvWrite(session, { key, value })</code> — persists to <code>store</code> + invalidates the cache entry, emits <code>kv.write</code></li><li><code>kvRangeQuery(session, { prefix, limit })</code> — returns <code>{ matches: string[], step }</code> with a lexicographically sorted match array + a single <code>kv.read</code> step</li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes read-your-writes on a replica; when the write lands on the primary and the reader hits a lagging replica, the merchant app returns stale data. Test catches it by asserting <code>state === &#39;eventually-consistent&#39;</code> on the replica read.</p><h2 id="axis-4-—-geo-replicated" tabindex="-1">Axis 4 — Geo-replicated <a class="header-anchor" href="#axis-4-—-geo-replicated" aria-label="Permalink to &quot;Axis 4 — Geo-replicated&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce multi-region consistency — a primary region that accepts writes and N replica regions that catch up asynchronously. Behind Cloudflare Smart Placement + KV replication, Vercel Edge Config replication, and Deno KV&#39;s primary/replica topology.</p><p><strong>State machine</strong>. <code>in-sync</code> → <code>lagging</code> (on <code>geoPrimaryWrite</code> or <code>markReplicaLagged</code>) → <code>in-sync</code> (only when every replica lag returns to 0) / <code>conflict-detected</code> → <code>in-sync</code> (on <code>resolveConflict</code>).</p><p><strong>Key functions</strong>.</p><ul><li><code>createGeoReplicatedSession({ platform, primaryRegion, replicaRegions })</code> — opens a session in <code>in-sync</code> at version 0</li><li><code>geoPrimaryWrite(session, { data })</code> — bumps version, marks every replica lagging (<code>POST_WRITE_LAG_MS</code> = 100 ms), emits <code>geo.primary-write</code></li><li><code>markReplicaLagged(session, { region, lagMs })</code> — records lag for a specific replica, emits <code>geo.replica-lagged</code></li><li><code>syncReplica(session, { region })</code> — clears lag on a replica, transitions to <code>in-sync</code> iff every replica has 0 lag, emits <code>geo.replica-synced</code></li><li><code>resolveConflict(session, { region, chosenVersion })</code> — picks a winning version, forces state back to <code>in-sync</code>, emits <code>geo.conflict-resolved</code></li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes a partial sync means the session is <code>in-sync</code>; it flips back only when <strong>every</strong> replica has zero lag. Test catches it by asserting <code>state === &#39;lagging&#39;</code> until every replica syncs.</p><h2 id="axis-5-—-cron-trigger" tabindex="-1">Axis 5 — Cron trigger <a class="header-anchor" href="#axis-5-—-cron-trigger" aria-label="Permalink to &quot;Axis 5 — Cron trigger&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce scheduled invocation lifecycle. Cloudflare fires scheduled handlers from 3 sources (Cron Triggers + Queue consumers + Email routing), Vercel Cron jobs cover scheduled + queue, Deno Deploy cron covers scheduled + queue.</p><p><strong>State machine</strong>. <code>scheduled</code> → <code>running</code> → <code>completed</code> / <code>failed</code> (with retry back to <code>scheduled</code> until <code>maxRetries</code> is exhausted).</p><p><strong>Key functions</strong>.</p><ul><li><code>scheduleCron({ id, platform, triggerType, cronSpec, maxRetries })</code> — seeds the session in <code>scheduled</code>, emits <code>cron.scheduled</code>. <code>triggerType</code> defaults to <code>&#39;scheduled&#39;</code>; <code>maxRetries</code> defaults to 3.</li><li><code>startCron(session)</code> — transitions to <code>running</code>, stamps <code>startedAt</code>, emits <code>cron.started</code></li><li><code>completeCron(session, { durationMs })</code> — transitions to <code>completed</code>, emits <code>cron.completed</code></li><li><code>failCron(session, { reason })</code> — increments <code>retryCount</code>; re-schedules while retries remain, terminates in <code>failed</code> otherwise. Emits <code>cron.failed</code> with <code>willRetry</code> reflecting the decision.</li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes a queue trigger runs a different code path than a scheduled cron; both ride the same lifecycle. Test catches it by asserting <code>triggerType === &#39;queue&#39;</code> without a distinct state machine.</p><h2 id="axis-6-—-subrequest-limit" tabindex="-1">Axis 6 — Subrequest limit <a class="header-anchor" href="#axis-6-—-subrequest-limit" aria-label="Permalink to &quot;Axis 6 — Subrequest limit&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce the per-invocation outbound fetch budget. Cloudflare Workers default 50 on the free plan, Vercel + Deno enforce comparable ceilings.</p><p><strong>State machine</strong>. <code>ok</code> → <code>approaching-limit</code> (at warning threshold, 80% of limit by default) → <code>limited</code> (further fetches refused).</p><p><strong>Key functions</strong>.</p><ul><li><code>startSubrequestBudget({ platform, limit, warningThreshold })</code> — opens a budget with <code>limit</code> = 50 + <code>warningThreshold</code> = 40 by default</li><li><code>startSubrequest(session)</code> / <code>countSubrequest(session)</code> / <code>completeSubrequest(session)</code> / <code>remainingBudget(session)</code> — step through the budget</li></ul><p><strong>Failure mode caught</strong>. Merchant app fans out to 60 subrequests without checking <code>remainingBudget</code>; production hits the ceiling silently. Test catches it by asserting the terminal state matches the configured limit.</p><h2 id="axis-7-—-cpu-time-limit" tabindex="-1">Axis 7 — CPU time limit <a class="header-anchor" href="#axis-7-—-cpu-time-limit" aria-label="Permalink to &quot;Axis 7 — CPU time limit&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce the per-invocation compute budget. Cloudflare Workers 50 ms on the free plan, Vercel + Deno enforce comparable ceilings.</p><p><strong>State machine</strong>. <code>idle</code> → <code>running</code> (on <code>startCpu</code>) → <code>warning</code> (at threshold) → <code>throttled</code> (budget exhausted) / <code>completed</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>startCpuBudget({ platform, budgetMs, warningAtMs })</code> — opens a CPU budget with <code>budgetMs</code> = 50 + <code>warningAtMs</code> = 40 by default</li><li><code>startCpu(session)</code> / <code>tickCpu(session, { deltaMs })</code> / <code>completeCpu(session)</code> — step through the budget</li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes a fast-path code branch stays under budget; a rare edge case blows through the threshold and the invocation gets throttled. Test catches it by asserting <code>state === &#39;warning&#39;</code> before the terminal transition.</p><h2 id="axis-8-—-streaming-response" tabindex="-1">Axis 8 — Streaming Response <a class="header-anchor" href="#axis-8-—-streaming-response" aria-label="Permalink to &quot;Axis 8 — Streaming Response&quot;">​</a></h2><p><strong>Purpose</strong>. Reproduce chunked / SSE / websocket body delivery with backpressure. Edge runtimes stream responses through a bounded buffer.</p><p><strong>State machine</strong>. <code>open</code> → <code>backpressure</code> (when <code>bytesSent</code> exceeds <code>highWaterMark</code>) → <code>open</code> (on <code>resumeStream</code>) → <code>closed</code> (terminal).</p><p><strong>Delivery kinds</strong>. <code>chunked</code> / <code>sse</code> / <code>websocket</code>.</p><p><strong>Key functions</strong>.</p><ul><li><code>openStream({ id, platform, kind, highWaterMark })</code> — opens a stream in <code>open</code>, emits <code>stream.opened</code>. <code>kind</code> defaults to <code>chunked</code>; <code>highWaterMark</code> defaults to 65536 bytes.</li><li><code>sendChunk(session, { data })</code> — advances counters, emits <code>stream.chunk-sent</code> (below high-water) / <code>stream.backpressure</code> (above)</li><li><code>resumeStream(session)</code> — transitions <code>backpressure</code> → <code>open</code>, drains one high-water-mark worth of buffered bytes</li><li><code>closeStream(session, { reason })</code> — terminal transition, emits <code>stream.closed</code> with total chunks + bytes</li></ul><p><strong>Failure mode caught</strong>. Merchant app assumes <code>sendChunk</code> always succeeds; the client is on a slow connection and the buffer overflows. Test catches it by asserting the <code>stream.backpressure</code> step arrives before the merchant app pushes more data.</p><h2 id="platform-specific-fidelity-table" tabindex="-1">Platform-specific fidelity table <a class="header-anchor" href="#platform-specific-fidelity-table" aria-label="Permalink to &quot;Platform-specific fidelity table&quot;">​</a></h2><p>The 8 neutral axes above expose 32 neutral events. Each real platform emits a <strong>different string</strong> for the same neutral event; the mock keeps the neutral name in <code>step.neutralEvent</code> and the platform dialect in <code>step.platformEvent</code>. Fidelity tests can assert either — production tests usually assert on <code>platformEvent</code> for exact-match SSOT + <code>neutralEvent</code> for cross-platform portability.</p><table tabindex="0"><thead><tr><th>Axis</th><th>neutralEvent</th><th>Cloudflare</th><th>Vercel</th><th>Deno Deploy</th></tr></thead><tbody><tr><td>durable-object</td><td><code>durable-object.created</code></td><td><code>durable_object.created</code></td><td><code>edge_function.session_affinity.created</code></td><td><code>deploy.stateful_object.created</code></td></tr><tr><td>durable-object</td><td><code>durable-object.requested</code></td><td><code>durable_object.fetch</code></td><td><code>edge_function.session_affinity.request</code></td><td><code>deploy.stateful_fetch</code></td></tr><tr><td>durable-object</td><td><code>durable-object.alarm-fired</code></td><td><code>durable_object.alarm</code></td><td><code>edge_function.background_timer</code></td><td><code>deploy.cron.timer</code></td></tr><tr><td>durable-object</td><td><code>durable-object.storage-written</code></td><td><code>durable_object.storage.put</code></td><td><code>edge_config.write</code></td><td><code>deno_kv.atomic_write</code></td></tr><tr><td>websocket-edge</td><td><code>websocket.upgrade-requested</code></td><td><code>websocket_upgrade.requested</code></td><td><code>edge_websocket_upgrade.requested</code></td><td><code>deno_websocket_upgrade.requested</code></td></tr><tr><td>websocket-edge</td><td><code>websocket.accepted</code></td><td><code>websocket_upgrade.accepted</code></td><td><code>edge_websocket_upgrade.accepted</code></td><td><code>deno_websocket_upgrade.accepted</code></td></tr><tr><td>websocket-edge</td><td><code>websocket.message</code></td><td><code>websocket.message</code></td><td><code>edge_websocket.message</code></td><td><code>deno_websocket.message</code></td></tr><tr><td>websocket-edge</td><td><code>websocket.closed</code></td><td><code>websocket.close</code></td><td><code>edge_websocket.close</code></td><td><code>deno_websocket.close</code></td></tr><tr><td>edge-kv</td><td><code>kv.read</code></td><td><code>kv_get</code></td><td><code>edge_config.get</code></td><td><code>deno_kv.get</code></td></tr><tr><td>edge-kv</td><td><code>kv.write</code></td><td><code>kv_put</code></td><td><code>edge_config.set</code></td><td><code>deno_kv.set</code></td></tr><tr><td>edge-kv</td><td><code>kv.cache-hit</code></td><td><code>kv_cache.hit</code></td><td><code>edge_config.cache_hit</code></td><td><code>deno_kv.cache_hit</code></td></tr><tr><td>edge-kv</td><td><code>kv.cache-miss</code></td><td><code>kv_cache.miss</code></td><td><code>edge_config.cache_miss</code></td><td><code>deno_kv.cache_miss</code></td></tr><tr><td>geo-replicated</td><td><code>geo.primary-write</code></td><td><code>smart_placement.primary_write</code></td><td><code>edge_config.primary_write</code></td><td><code>deno_kv.primary_write</code></td></tr><tr><td>geo-replicated</td><td><code>geo.replica-lagged</code></td><td><code>kv_replication.lagged</code></td><td><code>edge_config.replica_lagged</code></td><td><code>deno_kv.replica_lagged</code></td></tr><tr><td>geo-replicated</td><td><code>geo.replica-synced</code></td><td><code>kv_replication.synced</code></td><td><code>edge_config.replica_synced</code></td><td><code>deno_kv.replica_synced</code></td></tr><tr><td>geo-replicated</td><td><code>geo.conflict-resolved</code></td><td><code>durable_object.conflict_resolved</code></td><td><code>edge_config.conflict_resolved</code></td><td><code>deno_kv.conflict_resolved</code></td></tr><tr><td>cron-trigger</td><td><code>cron.scheduled</code></td><td><code>scheduled_event.enqueued</code></td><td><code>vercel_cron.scheduled</code></td><td><code>deploy.cron.scheduled</code></td></tr><tr><td>cron-trigger</td><td><code>cron.started</code></td><td><code>scheduled_event.started</code></td><td><code>vercel_cron.started</code></td><td><code>deploy.cron.started</code></td></tr><tr><td>cron-trigger</td><td><code>cron.completed</code></td><td><code>scheduled_event.completed</code></td><td><code>vercel_cron.completed</code></td><td><code>deploy.cron.completed</code></td></tr><tr><td>cron-trigger</td><td><code>cron.failed</code></td><td><code>scheduled_event.failed</code></td><td><code>vercel_cron.failed</code></td><td><code>deploy.cron.failed</code></td></tr><tr><td>subrequest-limit</td><td><code>subrequest.started</code></td><td><code>subrequest.fetch</code></td><td><code>edge_function.fetch</code></td><td><code>deploy.fetch.started</code></td></tr><tr><td>subrequest-limit</td><td><code>subrequest.counted</code></td><td><code>subrequest.counted</code></td><td><code>edge_function.subrequest_counted</code></td><td><code>deploy.fetch.counted</code></td></tr><tr><td>subrequest-limit</td><td><code>subrequest.limited</code></td><td><code>subrequest.limit_exceeded</code></td><td><code>edge_function.subrequest_limited</code></td><td><code>deploy.fetch.limited</code></td></tr><tr><td>subrequest-limit</td><td><code>subrequest.completed</code></td><td><code>subrequest.completed</code></td><td><code>edge_function.fetch_completed</code></td><td><code>deploy.fetch.completed</code></td></tr><tr><td>cpu-time-limit</td><td><code>cpu.started</code></td><td><code>worker.cpu.started</code></td><td><code>edge_function.cpu_started</code></td><td><code>deploy.cpu.started</code></td></tr><tr><td>cpu-time-limit</td><td><code>cpu.budget-warning</code></td><td><code>worker.cpu.warning</code></td><td><code>edge_function.cpu_warning</code></td><td><code>deploy.cpu.warning</code></td></tr><tr><td>cpu-time-limit</td><td><code>cpu.limited</code></td><td><code>worker.cpu.limit_exceeded</code></td><td><code>edge_function.cpu_limited</code></td><td><code>deploy.cpu.limited</code></td></tr><tr><td>cpu-time-limit</td><td><code>cpu.completed</code></td><td><code>worker.cpu.completed</code></td><td><code>edge_function.cpu_completed</code></td><td><code>deploy.cpu.completed</code></td></tr><tr><td>streaming-response</td><td><code>stream.opened</code></td><td><code>response_stream.opened</code></td><td><code>edge_function.stream_opened</code></td><td><code>deploy.stream.opened</code></td></tr><tr><td>streaming-response</td><td><code>stream.chunk-sent</code></td><td><code>response_stream.chunk</code></td><td><code>edge_function.stream_chunk</code></td><td><code>deploy.stream.chunk</code></td></tr><tr><td>streaming-response</td><td><code>stream.backpressure</code></td><td><code>response_stream.backpressure</code></td><td><code>edge_function.stream_backpressure</code></td><td><code>deploy.stream.backpressure</code></td></tr><tr><td>streaming-response</td><td><code>stream.closed</code></td><td><code>response_stream.closed</code></td><td><code>edge_function.stream_closed</code></td><td><code>deploy.stream.closed</code></td></tr></tbody></table><p>The full fidelity coverage grid is built by <code>collectFidelityCoverage()</code> from <code>@kiwa/edge/semantics/fidelity</code>. Downstream release-gate tests assert <code>rows.length === 24</code> (3 platforms × 8 axes) to guarantee full cross-platform coverage.</p><h2 id="where-each-axis-lands-in-the-release-gate" tabindex="-1">Where each axis lands in the release gate <a class="header-anchor" href="#where-each-axis-lands-in-the-release-gate" aria-label="Permalink to &quot;Where each axis lands in the release gate&quot;">​</a></h2><p>The 3 v1.24 dogfood apps map to the 8 axes as follows.</p><table tabindex="0"><thead><tr><th>Dogfood app</th><th>Axes covered</th><th>Ops</th></tr></thead><tbody><tr><td><code>dogfood-cloudflare-workers-durable-object-app</code></td><td><code>durable-object</code> + <code>websocket-edge</code></td><td>8 (4 + 4)</td></tr><tr><td><code>dogfood-vercel-edge-function-app</code></td><td><code>geo-replicated</code> + <code>edge-kv</code> + <code>streaming-response</code></td><td>8 (3 + 3 + 2)</td></tr><tr><td><code>dogfood-deno-deploy-geo-app</code></td><td><code>geo-replicated</code> + <code>edge-kv</code> + <code>cron-trigger</code></td><td>8 (3 + 2 + 3)</td></tr></tbody></table><p>The remaining 2 axes (<code>subrequest-limit</code> + <code>cpu-time-limit</code>) are exercised via the semantics unit tests under <code>packages/edge/tests/semantics/*.test.ts</code> — merchant apps rarely surface them as user-observable behaviour, but the axes stay on the fidelity grid because every platform enforces them silently in production.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tutorials/42-cloudflare-durable-object">Tutorial 42 — Cloudflare Workers Durable Object</a></li><li><a href="./../tutorials/43-vercel-edge-streaming">Tutorial 43 — Vercel Edge streaming</a></li><li><a href="./../tutorials/44-deno-deploy-geo">Tutorial 44 — Deno Deploy geo</a></li><li><a href="./../migrations/v1.23-to-v1.24">Migration guide v1.23 → v1.24</a></li><li><a href="./modern-web-framework-testing">Modern web framework testing (Signal + Islands + edge runtime SSOT)</a></li></ul>',66)])])}const h=t(s,[["render",r]]);export{g as __pageData,h as default};
